def generate_inputs(device):
    x = torch.zeros(16, 32, 128, device=device, dtype=torch.float32)
    # For all batch/channel pairs, set contrasting values
    # End of each channel (positions 125-127): large positive
    # Start of each channel (positions 0-3): zero (already)
    for b in range(16):
        for c in range(32):
            x[b, c, 125:128] = 1000.0
            # Positions 0:4 stay at 0.0
    return [x]
